"""Class 9 Maths Ch 8 - Sequences and Progressions (sequences, AP, GP terms, sum of an AP). Answers computed in code."""
from g9m import *

SLUG, NAME, CHNO = "Sequences_and_Progressions", "Sequences and Progressions", 8

def apt(a, d, n): return a + (n - 1) * d
def aps(a, d, n): return n * (2 * a + (n - 1) * d) // 2
def gpt(a, r, n): return a * r ** (n - 1)
def L(a, d, k=4, geo=False): return lst(a, d, k, geo) + r",\ldots"
def sg(c, v, k="n"):  # linear expression c*n + v
    t = "" if c == 1 else ("-" if c == -1 else str(c))
    return f"{t}{k}" + (f"+{v}" if v > 0 else (f"-{-v}" if v < 0 else ""))

