HARD_C = ([QQ(f"The sum of the {p}th and {q}th terms of an AP is ${apt(a,d,p)+apt(a,d,q)}$ and its {r}th term is ${apt(a,d,r)}$. Find the AP's first term and the sum of its first {n} terms.", f"$2a+{p+q-2}d={apt(a,d,p)+apt(a,d,q)}$ and $a+{r-1}d={apt(a,d,r)}$", f"Solving: $a={a}$, $d={d}$", f"$S_{{{n}}}={aps(a,d,n)}$") for a, d, p, q, r, n in [(5, 3, 3, 9, 6, 20), (12, 4, 2, 10, 5, 14), (-4, 7, 4, 8, 7, 12), (30, -2, 5, 11, 9, 16), (8, 6, 3, 7, 10, 13), (2, 5, 6, 12, 4, 25)]]
          + [QQ(f"Find the sum of all natural numbers between {lo} and {hi} that leave remainder {rem} when divided by {k}.", f"Terms: ${lst(first, k, 3)},\\ldots,{last}$", f"Number of terms $={cnt}$", f"Sum $=\\frac n2(a+l)={tot}$") for k, rem, lo, hi in [(5, 2, 10, 200), (7, 3, 20, 300), (4, 1, 15, 150), (9, 4, 30, 250), (6, 5, 10, 180), (8, 3, 40, 260)]
             for first, last, cnt, tot in [(lambda xs: (xs[0], xs[-1], len(xs), sum(xs)))([x for x in range(lo + 1, hi) if x % k == rem])]]
          + [QQ(f"Three positive numbers are in GP. Their product is ${m**3}$ and the sum of the first and third is ${m//r+m*r}$. Find the numbers.", "Let them be $\\frac mr,\\ m,\\ mr$", f"Product $=m^3={m**3}$, so $m={m}$", f"$\\frac{{{m}}}r+{m}r={m//r+m*r}$ gives $r={r}$", f"Numbers ${m//r}$, ${m}$, ${m*r}$") for m, r in [(6, 2), (12, 3), (20, 4), (15, 3), (24, 2), (30, 5)]])
HARD_D = ([QQ(f"A contractor pays a penalty for delay: ₹{a} on day 1, ₹{a+d} on day 2, ₹{a+2*d} on day 3 and so on. If the work is {n} days late, find the penalty on the last day and the total penalty.", "Penalties form an AP", f"$t_{{{n}}}={a}+{n-1}\\times{d}={apt(a,d,n)}$", "$S_n=\\frac n2(a+l)$", f"$S_{{{n}}}=\\frac{{{n}}}2({a}+{apt(a,d,n)})$", f"Total ₹{aps(a,d,n)}") for a, d, n in [(200, 50, 30), (100, 25, 24), (500, 100, 18), (150, 30, 28), (80, 20, 35), (250, 40, 22)]]
          + [QQ(f"A ball is dropped from {h} m and rebounds to {r}/{r+1} of the previous height. Show that the rebound heights form a GP and find the 3rd rebound height.", f"Ratio $\\frac{{{r}}}{{{r+1}}}$ is constant, so a GP", f"1st rebound $={h*r//(r+1)}$ m", f"3rd rebound $=h\\times({r}/{r+1})^3$", f"$={h*r**3//(r+1)**3}$ m") for h, r in [(81, 2), (64, 3), (125, 4), (256, 3), (1000, 4), (162, 2)]])

TIERS = T4((NCERT_A, NCERT_B, NCERT_C, NCERT_D), (EASY_A, EASY_B, EASY_C, EASY_D), (MED_A, MED_B, MED_C, MED_D), (HARD_A, HARD_B, HARD_C, HARD_D))
